import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js';
// Reusable GPU-driven WebGL effects; no HTML/CSS overlays.
export function createPortalMaterial(){return new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.DoubleSide,uniforms:{uTime:{value:0},uViolet:{value:new THREE.Color(0x885aff)},uCyan:{value:new THREE.Color(0x63e5ff)}},vertexShader:`varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,fragmentShader:`varying vec2 vUv;uniform float uTime;uniform vec3 uViolet,uCyan;void main(){vec2 uv=vUv-.5;float a=atan(uv.y,uv.x);float r=length(uv);float swirl=sin(a*7.-r*25.+uTime*2.)*.07;float ripples=sin(r*72.-uTime*4.+swirl*8.);float core=smoothstep(.49,.12,r);float edge=pow(1.-smoothstep(.35,.5,r),1.5);vec3 col=mix(uViolet,uCyan,clamp(.5+.5*sin(a*3.+uTime+r*10.),0.,1.));col*=.48+.52*ripples*ripples;float alpha=core*edge*.92;gl_FragColor=vec4(col,alpha);}`})}
export function createCodeField({count=400,radius=60,height=80,rising=false}={}){
 const geo=new THREE.BufferGeometry(),coords=new Float32Array(count*3),speed=new Float32Array(count),phase=new Float32Array(count);
 for(let i=0;i<count;i++){const a=i*2.399963229728653,r=radius*(.25+.75*Math.sqrt((i+.5)/count));coords[3*i]=Math.cos(a)*r;coords[3*i+1]=((i*97)%count)/count*height-height/2;coords[3*i+2]=Math.sin(a)*r;speed[i]=.45+(i%19)/15;phase[i]=(i%43)/43;}
 geo.setAttribute('position',new THREE.BufferAttribute(coords,3));geo.setAttribute('aSpeed',new THREE.BufferAttribute(speed,1));geo.setAttribute('aPhase',new THREE.BufferAttribute(phase,1));
 const mat=new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,uniforms:{uTime:{value:0},uHeight:{value:height},uDirection:{value:rising?1:-1},uColor:{value:new THREE.Color(rising?0x6bceff:0x986aff)}},vertexShader:`attribute float aSpeed;attribute float aPhase;uniform float uTime,uHeight,uDirection;varying float vAlpha;void main(){vec3 p=position;p.y=mod(p.y+uHeight*.5+uDirection*uTime*aSpeed*9.+aPhase*13.,uHeight)-uHeight*.5;vAlpha=.25+.75*pow(abs(sin(aPhase*35.+uTime*.9)),2.);gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.);gl_PointSize=clamp(64./max(1.,-gl_Position.z),1.5,6.);}`,fragmentShader:`uniform vec3 uColor;varying float vAlpha;void main(){vec2 q=gl_PointCoord-.5;float bar=smoothstep(.29,.04,abs(q.x))*smoothstep(.5,.1,abs(q.y));gl_FragColor=vec4(uColor,bar*vAlpha);}`});
 const points=new THREE.Points(geo,mat);points.frustumCulled=false;points.userData.update=t=>{mat.uniforms.uTime.value=t};return points;
}
export function updateShaderTime(object,t){object.traverse(o=>{if(o.material?.uniforms?.uTime)o.material.uniforms.uTime.value=t;if(o.userData?.update)o.userData.update(t)})}
